<script setup>
import { onMounted, reactive, ref } from 'vue';
import TrackingTimeline from '../common/TrackingTimeline.vue';
import { useReturnStore } from '../../stores/return';

const props = defineProps({ returnItem: { type: Object, required: true } });
const emit = defineEmits(['close', 'processed']);
const store = useReturnStore(); const tab = ref('decision'); const saving = ref(false); const error = ref(''); const confirmed = ref(false);
const form = reactive({ action: 'reattempt', reason_code: 'Failed delivery review', notes: '' });
const submit = async () => { if (form.action === 'dispose' && !confirmed.value) { error.value = 'Please confirm package disposal before submitting.'; return; } saving.value = true; error.value = ''; try { await store.processAction(props.returnItem.id, form); emit('processed'); } catch (e) { error.value = e.response?.data?.message || 'Return decision could not be saved.'; } finally { saving.value = false; } };
onMounted(() => store.fetchHistory(props.returnItem.order_id));
</script>

<template>
  <div class="fixed inset-0 z-40 flex items-center justify-center bg-slate-950/50 p-4" @click.self="emit('close')"><section class="flex max-h-[90vh] w-full max-w-4xl flex-col bg-white shadow-2xl"><header class="flex items-start justify-between border-b border-slate-200 p-6"><div><p class="text-xs font-black uppercase tracking-widest text-teal-700">Reverse logistics decision</p><h2 class="mt-1 text-2xl font-black">{{ returnItem.order?.awb_number }}</h2><p class="mt-1 text-sm text-slate-500">{{ returnItem.order?.recipient_name }} · {{ returnItem.return_reason.replaceAll('_', ' ') }}</p></div><button class="text-2xl text-slate-400" aria-label="Close" @click="emit('close')">&times;</button></header><div class="flex border-b border-slate-200 px-6"><button class="border-b-2 px-3 py-3 text-sm font-bold" :class="tab === 'decision' ? 'border-teal-600 text-teal-700' : 'border-transparent text-slate-400'" @click="tab = 'decision'">Decision</button><button class="border-b-2 px-3 py-3 text-sm font-bold" :class="tab === 'history' ? 'border-teal-600 text-teal-700' : 'border-transparent text-slate-400'" @click="tab = 'history'">Tracking history</button></div><div class="overflow-y-auto p-6"><form v-if="tab === 'decision'" @submit.prevent="submit"><div class="grid gap-3 md:grid-cols-3"><label v-for="option in [{ value: 'reattempt', title: 'Re-attempt delivery', text: 'Send back to dispatch queue.' }, { value: 'rts', title: 'Return to sender', text: 'Route back to origin hub.' }, { value: 'dispose', title: 'Dispose package', text: 'Permanent destructive action.' }]" :key="option.value" class="cursor-pointer border p-4" :class="form.action === option.value ? option.value === 'dispose' ? 'border-red-500 bg-red-50' : 'border-teal-500 bg-teal-50' : 'border-slate-200'"><input v-model="form.action" type="radio" :value="option.value" class="mr-2" @change="confirmed = false" /><strong class="text-sm">{{ option.title }}</strong><span class="mt-2 block text-xs text-slate-500">{{ option.text }}</span></label></div><div class="mt-5 grid gap-4 md:grid-cols-2"><label class="text-sm font-bold">Reason code<select v-model="form.reason_code" class="mt-1 w-full border px-3 py-2"><option>Failed delivery review</option><option>Customer refusal confirmed</option><option>Incorrect address verified</option><option>Damaged goods disposition</option><option>Expired holding period</option></select></label><label class="text-sm font-bold">Decision notes<textarea v-model="form.notes" required rows="4" class="mt-1 w-full border px-3 py-2" placeholder="Explain the decision..." /></label></div><label v-if="form.action === 'dispose'" class="mt-4 flex items-start gap-2 bg-red-50 p-4 text-sm font-semibold text-red-800"><input v-model="confirmed" type="checkbox" class="mt-1" /> I understand this permanently disposes of the package and cannot be reversed.</label><p v-if="error" class="mt-4 bg-red-50 px-4 py-3 text-sm text-red-700">{{ error }}</p><div class="mt-6 flex justify-end gap-3"><button type="button" class="px-4 py-2 text-sm font-bold text-slate-600" @click="emit('close')">Cancel</button><button :disabled="saving || (form.action === 'dispose' && !confirmed)" class="px-5 py-2 text-sm font-bold text-white disabled:opacity-40" :class="form.action === 'dispose' ? 'bg-red-700' : 'bg-slate-950'">{{ saving ? 'Saving...' : 'Apply decision' }}</button></div></form><TrackingTimeline v-else :history-items="store.history" /></div></section></div>
</template>